package com.universe.community.controller; import com.universe.community.dto.request.*; import com.universe.community.dto.response.CommentResponse; import com.universe.community.service.CommentService; import com.universe.global.common.*; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; @RestController @RequiredArgsConstructor public class CommentController {private final CommentService service; @GetMapping("/api/v1/community/posts/{postId}/comments") public ApiResponse<PageResponse<CommentResponse>> list(@PathVariable Long postId,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ApiResponse.success(service.list(postId,page,size));} @PostMapping("/api/v1/community/posts/{postId}/comments") public ApiResponse<CommentResponse> create(@PathVariable Long postId,@Valid @RequestBody CommentCreateRequest r){return ApiResponse.success(service.create(postId,r));} @PatchMapping("/api/v1/community/comments/{commentId}") public ApiResponse<CommentResponse> update(@PathVariable Long commentId,@Valid @RequestBody CommentUpdateRequest r){return ApiResponse.success(service.update(commentId,r));} @DeleteMapping("/api/v1/community/comments/{commentId}") public ApiResponse<Void> delete(@PathVariable Long commentId){service.delete(commentId);return ApiResponse.success();}}
